    function allowance(address _owner, address _spender) external view returns (uint remaining);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        // Fund the attacker with 10,000 USDT (Tether has 6 decimals)
        deal(TARGET, attacker, 10_000 * 1e6);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Define a spender address for the test
                address spender = address(0xDEADBEEF);

                // 1. Initial approval of a non-zero amount. This succeeds because the current allowance is 0.
                TetherToken(TARGET).approve(spender, 100);

                // We can assert that the allowance is now 100.
                assertEq(TetherToken(TARGET).allowance(attacker, spender), 100);

                // 2. To change the allowance, we must first approve 0.
                TetherToken(TARGET).approve(spender, 0);

                // Assert that the allowance is now 0.
                assertEq(TetherToken(TARGET).allowance(attacker, spender), 0);

